BEGIN;
CREATE TABLE IF NOT EXISTS course_deliveries(id text PRIMARY KEY,enrollment_id text NOT NULL,course_id text NOT NULL,department_id text,instructor_id text,completed_record_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS course_delivery_enrollment_uniq ON course_deliveries(enrollment_id);
CREATE UNIQUE INDEX IF NOT EXISTS course_delivery_completion_uniq ON course_deliveries(completed_record_id);
CREATE INDEX IF NOT EXISTS course_delivery_instructor_idx ON course_deliveries(instructor_id);
CREATE INDEX IF NOT EXISTS course_delivery_department_idx ON course_deliveries(department_id);
CREATE TABLE IF NOT EXISTS course_feedback(id text PRIMARY KEY,employee_id text NOT NULL,completion_record_id text NOT NULL,course_id text NOT NULL,delivery_id text,department_id text,rating integer NOT NULL,comment text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,comment_hidden boolean NOT NULL DEFAULT false,excluded boolean NOT NULL DEFAULT false,moderation_reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS course_feedback_employee_completion_uniq ON course_feedback(employee_id,completion_record_id);
CREATE INDEX IF NOT EXISTS course_feedback_scope_time_idx ON course_feedback(department_id,course_id,created_at);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='course_feedback_valid') THEN ALTER TABLE course_feedback ADD CONSTRAINT course_feedback_valid CHECK(rating BETWEEN 1 AND 5 AND revision > 0 AND char_length(comment) <= 2000); END IF; END $$;
CREATE TABLE IF NOT EXISTS instructor_feedback(id text PRIMARY KEY,employee_id text NOT NULL,completion_record_id text NOT NULL,course_id text NOT NULL,delivery_id text,department_id text,instructor_id text NOT NULL,rating integer NOT NULL,comment text NOT NULL DEFAULT '',revision integer NOT NULL DEFAULT 1,comment_hidden boolean NOT NULL DEFAULT false,excluded boolean NOT NULL DEFAULT false,moderation_reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS instructor_feedback_employee_completion_uniq ON instructor_feedback(employee_id,completion_record_id);
CREATE INDEX IF NOT EXISTS instructor_feedback_scope_time_idx ON instructor_feedback(department_id,instructor_id,created_at);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='instructor_feedback_valid') THEN ALTER TABLE instructor_feedback ADD CONSTRAINT instructor_feedback_valid CHECK(rating BETWEEN 1 AND 5 AND revision > 0 AND char_length(comment) <= 2000); END IF; END $$;
CREATE TABLE IF NOT EXISTS feedback_revisions(id text PRIMARY KEY,kind text NOT NULL,response_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,revision integer NOT NULL,old_rating integer,new_rating integer NOT NULL,old_comment text,new_comment text NOT NULL,old_hidden boolean,new_hidden boolean NOT NULL,old_excluded boolean,new_excluded boolean NOT NULL,reason text NOT NULL DEFAULT '',request_id text NOT NULL,at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS feedback_revision_request_uniq ON feedback_revisions(request_id);
CREATE UNIQUE INDEX IF NOT EXISTS feedback_revision_number_uniq ON feedback_revisions(kind,response_id,revision);
CREATE INDEX IF NOT EXISTS feedback_revision_cutoff_idx ON feedback_revisions(kind,response_id,at);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='feedback_revision_valid') THEN ALTER TABLE feedback_revisions ADD CONSTRAINT feedback_revision_valid CHECK(kind IN ('course','instructor') AND action IN ('create','edit','moderate') AND revision > 0 AND new_rating BETWEEN 1 AND 5); END IF; END $$;
CREATE TABLE IF NOT EXISTS feedback_digest_runs(id text PRIMARY KEY,recipient_id text NOT NULL,interval_kind text NOT NULL,kind text NOT NULL,period_start timestamptz NOT NULL,period_end timestamptz NOT NULL,completed_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS feedback_digest_period_uniq ON feedback_digest_runs(recipient_id,interval_kind,kind,period_start);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conname='feedback_digest_period_valid') THEN ALTER TABLE feedback_digest_runs ADD CONSTRAINT feedback_digest_period_valid CHECK(interval_kind IN ('week','month') AND kind IN ('course','instructor') AND period_end>period_start); END IF; END $$;
COMMIT;
